//! Helpers shared by the analysis tests. Each test file uses some of them.
#![allow(dead_code)]

use mesh_analysis::Analysis;
use mesh_syntax::Span;

/// Parses and lowers `source`, then analyzes it as the template of
/// `template` in `manifest`.
pub fn analyze(manifest: &str, template: &str, source: &str) -> Analysis {
    let manifest = mesh_manifest::load(manifest).expect("the test manifest loads");
    let template = manifest
        .template(template)
        .expect("the template is declared");
    let ast = mesh_parser::parse(source).ast.expect("the source parses");
    let ir = mesh_semantic::lower(&ast).ir.expect("the source lowers");
    mesh_analysis::analyze(&ir, template)
}

/// The span of the `n`th (0-based) occurrence of `needle` in `source`.
pub fn nth(source: &str, needle: &str, n: usize) -> Span {
    let start_byte = source
        .match_indices(needle)
        .nth(n)
        .unwrap_or_else(|| panic!("{needle:?} occurs fewer than {} times", n + 1))
        .0;
    Span {
        start_byte,
        end_byte: start_byte + needle.len(),
    }
}

/// The span of the first occurrence of `needle` in `source`.
pub fn at(source: &str, needle: &str) -> Span {
    nth(source, needle, 0)
}

pub fn names(names: &[&str]) -> Vec<String> {
    names.iter().map(|name| name.to_string()).collect()
}

//! Analysis of real MPRX source against a small manifest: the source is
//! parsed and lowered, then analyzed as the template of `view`.

mod common;

use common::{at, names, nth};
use mesh_analysis::{Analysis, Fact, Resolution, Target};
use mesh_syntax::Span;

const MANIFEST: &str = r#"{
  "version": 1,
  "types": {
    "User": { "kind": "record", "fields": {
      "name": { "type": { "kind": "string" }, "required": true }
    } }
  },
  "components": {
    "page": {
      "props": {
        "title": { "type": { "kind": "string" }, "required": true },
        "subtitle": { "type": { "kind": "string" }, "required": false }
      },
      "events": {}, "commands": {}, "scope": {}
    },
    "card": {
      "props": {
        "user": { "type": { "kind": "named", "name": "User" }, "required": true },
        "note": { "type": { "kind": "optional", "type": { "kind": "string" } }, "required": true }
      },
      "events": {
        "select": { "payload": { "kind": "named", "name": "User" } },
        "close": {}
      },
      "commands": {}, "scope": {}
    },
    "view": {
      "props": {}, "events": {},
      "commands": {
        "log": { "parameters": [{ "name": "value", "type": { "kind": "any" } }] },
        "save": { "parameters": [] },
        "select": { "parameters": [{ "name": "user", "type": { "kind": "named", "name": "User" } }] }
      },
      "scope": {
        "user": { "kind": "named", "name": "User" },
        "count": { "kind": "number" }
      }
    }
  }
}"#;

fn analyze(source: &str) -> Analysis {
    common::analyze(MANIFEST, "view", source)
}

#[test]
fn a_template_that_matches_its_manifest_has_no_facts() {
    let source = r#"<page title="Users">
  <card user={user} note={user.name} on.select={select($event)} on.close={save()} />
</page>"#;
    assert_eq!(analyze(source).facts(), []);
}

#[test]
fn resolves_every_name_against_the_manifest() {
    let source =
        r#"<card user={user} note={count == 1 ? "one" : "many"} on.select={select($event)} />"#;
    let target = |span: Span| {
        analyze(source)
            .resolutions()
            .iter()
            .find(|resolution| resolution.span == span)
            .map(|resolution| resolution.target.clone())
    };
    assert_eq!(
        target(at(source, "card")),
        Some(Target::Component("card".to_string()))
    );
    assert_eq!(
        target(at(source, "user")),
        Some(Target::Prop {
            component: "card".to_string(),
            prop: "user".to_string(),
        })
    );
    assert_eq!(
        target(nth(source, "user", 1)),
        Some(Target::Scope("user".to_string()))
    );
    assert_eq!(
        target(at(source, "count")),
        Some(Target::Scope("count".to_string()))
    );
    assert_eq!(
        target(nth(source, "select", 0)),
        Some(Target::Event {
            component: "card".to_string(),
            event: "select".to_string(),
        })
    );
    assert_eq!(
        target(nth(source, "select", 1)),
        Some(Target::Command("select".to_string()))
    );
    assert_eq!(
        target(at(source, "note")),
        Some(Target::Prop {
            component: "card".to_string(),
            prop: "note".to_string(),
        })
    );
    assert_eq!(analyze(source).resolutions().len(), 7);
}

#[test]
fn reports_an_unknown_component_once_and_still_checks_its_expressions() {
    let source = r#"<crad user={usr} on.select={select($event)} />"#;
    assert_eq!(
        analyze(source).facts(),
        [
            Fact::UnknownComponent {
                name: "crad".to_string(),
                span: at(source, "crad"),
                candidates: names(&["card", "page", "view"]),
            },
            Fact::UnknownReference {
                name: "usr".to_string(),
                span: at(source, "usr"),
                candidates: names(&["count", "user"]),
            },
        ]
    );
}

#[test]
fn reports_unknown_props_and_events_with_the_components_names() {
    let source = r#"<card user={user} note={user.name} colour="red" on.selct={save()} />"#;
    assert_eq!(
        analyze(source).facts(),
        [
            Fact::UnknownProp {
                component: "card".to_string(),
                prop: "colour".to_string(),
                span: at(source, "colour"),
                candidates: names(&["note", "user"]),
            },
            Fact::UnknownEvent {
                component: "card".to_string(),
                event: "selct".to_string(),
                span: at(source, "selct"),
                candidates: names(&["close", "select"]),
            },
        ]
    );
}

/// D5: requiredness belongs to the declaration. `note: string?` must be
/// supplied even though its value may be absent; `subtitle?: string`
/// may be omitted.
#[test]
fn reports_each_missing_required_prop_at_the_tag() {
    let source = r#"<page><card /></page>"#;
    assert_eq!(
        analyze(source).facts(),
        [
            Fact::MissingRequiredProp {
                component: "page".to_string(),
                prop: "title".to_string(),
                span: at(source, "page"),
            },
            Fact::MissingRequiredProp {
                component: "card".to_string(),
                prop: "note".to_string(),
                span: at(source, "card"),
            },
            Fact::MissingRequiredProp {
                component: "card".to_string(),
                prop: "user".to_string(),
                span: at(source, "card"),
            },
        ]
    );
}

#[test]
fn reports_unknown_references_and_commands() {
    let source =
        r#"<page title={titel}><card user={user} note={user.name} on.close={sav()} /></page>"#;
    assert_eq!(
        analyze(source).facts(),
        [
            Fact::UnknownReference {
                name: "titel".to_string(),
                span: at(source, "titel"),
                candidates: names(&["count", "user"]),
            },
            Fact::UnknownCommand {
                command: "sav".to_string(),
                span: at(source, "sav"),
                candidates: names(&["log", "save", "select"]),
            },
        ]
    );
}

#[test]
fn checks_command_arity_and_still_checks_the_arguments() {
    let source = r#"<card user={user} note={user.name} on.select={select($event, usr)} on.close={save(1)} />"#;
    assert_eq!(
        analyze(source).facts(),
        [
            Fact::CommandArityMismatch {
                command: "select".to_string(),
                expected: 1,
                found: 2,
                span: at(source, "select($event, usr)"),
            },
            Fact::UnknownReference {
                name: "usr".to_string(),
                span: at(source, "usr"),
                candidates: names(&["count", "user"]),
            },
            Fact::CommandArityMismatch {
                command: "save".to_string(),
                expected: 0,
                found: 1,
                span: at(source, "save(1)"),
            },
        ]
    );
}

/// D10: a command is valid only as the complete handler expression. A
/// misplaced command is reported once, and nothing inside it is checked.
#[test]
fn a_command_is_valid_only_as_a_whole_handler() {
    for (source, command) in [
        (r#"<page title={save()} />"#, "save()"),
        (r#"<page title="t">{save()}</page>"#, "save()"),
        (r#"<page title="t">{!save()}</page>"#, "save()"),
        (r#"<page title={[nope(usr)]} />"#, "nope(usr)"),
        (
            r#"<card user={user} note={user.name} on.select={select(save())} />"#,
            "save()",
        ),
    ] {
        let name = command.split('(').next().expect("has a name");
        assert_eq!(
            analyze(source).facts(),
            [Fact::CommandOutsideHandler {
                command: name.to_string(),
                span: at(source, command),
            }],
            "{source}"
        );
    }
}

#[test]
fn a_handler_must_be_a_command_and_is_not_looked_inside() {
    let source = r#"<card user={user} note={user.name} on.select={usr.name} on.close={$event} />"#;
    assert_eq!(
        analyze(source).facts(),
        [
            Fact::HandlerNotCommand {
                event: "select".to_string(),
                span: at(source, "usr.name"),
            },
            Fact::HandlerNotCommand {
                event: "close".to_string(),
                span: at(source, "$event"),
            },
        ]
    );
}

/// D10: `$event` exists only inside the arguments of an `on.` handler's
/// command, at any depth.
#[test]
fn event_value_is_valid_only_in_handler_arguments() {
    let valid = r#"<card user={user} note={user.name} on.select={log({ users: [$event] })} />"#;
    assert_eq!(analyze(valid).facts(), []);

    for source in [
        r#"<page title={$event} />"#,
        r#"<page title="t">{$event}</page>"#,
    ] {
        assert_eq!(
            analyze(source).facts(),
            [Fact::EventValueOutsideHandler {
                span: at(source, "$event"),
            }],
            "{source}"
        );
    }
}

#[test]
fn event_value_needs_a_payload() {
    let source = r#"<card user={user} note={user.name} on.close={select($event)} />"#;
    assert_eq!(
        analyze(source).facts(),
        [Fact::EventHasNoPayload {
            component: "card".to_string(),
            event: "close".to_string(),
            span: at(source, "$event"),
        }]
    );
}

/// An unknown event or component is reported once; `$event` in its
/// handler isn't reported again.
#[test]
fn event_value_under_an_unknown_event_is_not_reported_again() {
    let source = r#"<crad on.select={select($event)} />"#;
    assert_eq!(analyze(source).facts().len(), 1);
    let source = r#"<card user={user} note={user.name} on.pick={select($event)} />"#;
    assert_eq!(analyze(source).facts().len(), 1);
}

#[test]
fn only_event_is_a_special_value() {
    let source = r#"<card user={user} note={$evnt} on.select={select($target)} />"#;
    assert_eq!(
        analyze(source).facts(),
        [
            Fact::UnknownSpecialValue {
                name: "evnt".to_string(),
                span: at(source, "$evnt"),
                candidates: names(&["event"]),
            },
            Fact::UnknownSpecialValue {
                name: "target".to_string(),
                span: at(source, "$target"),
                candidates: names(&["event"]),
            },
        ]
    );
}

/// Facts come out in source order even though the walk visits an
/// element's attributes before its event bindings.
#[test]
fn facts_are_in_source_order() {
    let source = r#"<card on.pick={sav()} usr={a} note={b} />"#;
    let starts: Vec<usize> = analyze(source)
        .facts()
        .iter()
        .map(|fact| fact.span().start_byte)
        .collect();
    let mut sorted = starts.clone();
    sorted.sort();
    assert_eq!(starts, sorted);
    assert_eq!(starts.len(), 6, "{:#?}", analyze(source).facts());
}

#[test]
fn resolutions_record_only_names_that_resolved() {
    let source = r#"<crad title={usr} />"#;
    assert_eq!(analyze(source).resolutions(), [] as [Resolution; 0]);
}

//! Semantic analysis for MPRX: checks a template's Semantic IR against the
//! component manifest it is the template of.
//!
//! [`analyze`] resolves every name in the IR against the manifest: each
//! element's tag to a component, its attributes to that component's props
//! and its `on.` bindings to its events, and every reference and command to
//! the template's own scope and commands. It also checks that required
//! props are supplied and that commands and `$event` appear only where
//! they may.
//!
//! Analysis never changes the IR. Its results are kept beside it, in the
//! returned [`Analysis`]: what each name resolved to, and a [`Fact`] for
//! each problem found. Facts are data, not prose; turning them into
//! diagnostics (codes, messages and suggestions) is `mesh-compiler`'s job.

use mesh_manifest::Template;
use mesh_syntax::Span;

mod check;

/// Analyzes `ir` as the template of `template`'s component.
pub fn analyze(ir: &mesh_semantic::Element, template: Template<'_>) -> Analysis {
    check::analyze(ir, template)
}

/// The results of analyzing one template: kept beside the IR, never
/// written into it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Analysis {
    facts: Vec<Fact>,
    resolutions: Vec<Resolution>,
}

impl Analysis {
    /// Every problem found, in source order: sorted by the start of each
    /// fact's span, and in the order they were found where two start at
    /// the same byte.
    pub fn facts(&self) -> &[Fact] {
        &self.facts
    }

    /// What each name that resolved refers to, in the order analysis met
    /// them. A name that didn't resolve has a [`Fact`] instead.
    pub fn resolutions(&self) -> &[Resolution] {
        &self.resolutions
    }
}

/// A name in the template, and the manifest declaration it refers to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Resolution {
    /// The name as written: a tag name, attribute name, event name,
    /// reference or command name.
    pub span: Span,
    pub target: Target,
}

/// The manifest declaration a name resolved to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Target {
    /// A component, by tag name.
    Component(String),
    /// A prop of a component.
    Prop { component: String, prop: String },
    /// An event of a component.
    Event { component: String, event: String },
    /// A name in the template's scope.
    Scope(String),
    /// A command of the template's component.
    Command(String),
}

/// A problem analysis found, with the context a diagnostic needs.
///
/// Facts hold no prose and no suggestions: `candidates` lists the names
/// that *were* available, and choosing a close one is the diagnostic
/// layer's job. Candidates are in the manifest's (sorted) order.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Fact {
    /// An element's tag names no component. Span: the tag name.
    UnknownComponent {
        name: String,
        span: Span,
        candidates: Vec<String>,
    },
    /// An attribute isn't a prop of the element's component. Span: the
    /// attribute name.
    UnknownProp {
        component: String,
        prop: String,
        span: Span,
        candidates: Vec<String>,
    },
    /// An element omits a prop its component declares required. Span: the
    /// element's tag name.
    MissingRequiredProp {
        component: String,
        prop: String,
        span: Span,
    },
    /// An `on.` binding names an event the component doesn't have. Span:
    /// the event name.
    UnknownEvent {
        component: String,
        event: String,
        span: Span,
        candidates: Vec<String>,
    },
    /// A reference isn't in the template's scope. Span: the reference.
    UnknownReference {
        name: String,
        span: Span,
        candidates: Vec<String>,
    },
    /// A command the template's component doesn't declare. Span: the
    /// command name.
    UnknownCommand {
        command: String,
        span: Span,
        candidates: Vec<String>,
    },
    /// A command invoked with the wrong number of arguments. Span: the
    /// whole invocation.
    CommandArityMismatch {
        command: String,
        expected: usize,
        found: usize,
        span: Span,
    },
    /// A command invoked anywhere but as the whole handler of an `on.`
    /// binding. Span: the whole invocation.
    CommandOutsideHandler { command: String, span: Span },
    /// An `on.` handler that isn't a command invocation. Span: the
    /// handler expression.
    HandlerNotCommand { event: String, span: Span },
    /// `$event` outside the arguments of an `on.` handler's command.
    EventValueOutsideHandler { span: Span },
    /// `$event` in the handler of an event that declares no payload.
    EventHasNoPayload {
        component: String,
        event: String,
        span: Span,
    },
    /// A `$` name other than `$event`. `name` has no `$`.
    UnknownSpecialValue {
        name: String,
        span: Span,
        candidates: Vec<String>,
    },
}

impl Fact {
    /// The source span the fact is about.
    pub fn span(&self) -> Span {
        match self {
            Fact::UnknownComponent { span, .. }
            | Fact::UnknownProp { span, .. }
            | Fact::MissingRequiredProp { span, .. }
            | Fact::UnknownEvent { span, .. }
            | Fact::UnknownReference { span, .. }
            | Fact::UnknownCommand { span, .. }
            | Fact::CommandArityMismatch { span, .. }
            | Fact::CommandOutsideHandler { span, .. }
            | Fact::HandlerNotCommand { span, .. }
            | Fact::EventValueOutsideHandler { span }
            | Fact::EventHasNoPayload { span, .. }
            | Fact::UnknownSpecialValue { span, .. } => *span,
        }
    }
}

//! The analysis walk: one pass over the IR, from the root element down,
//! in source order within each element.

use crate::{Analysis, Fact, Resolution, Target};
use mesh_manifest::{Component, Template};
use mesh_semantic::{AttributeValue, Child, Element, Expression};
use mesh_syntax::Span;

pub(crate) fn analyze(ir: &Element, template: Template<'_>) -> Analysis {
    let mut walker = Walker {
        template,
        facts: Vec::new(),
        resolutions: Vec::new(),
    };
    walker.element(ir);
    let Walker {
        mut facts,
        resolutions,
        ..
    } = walker;
    // Stable, so facts that start at the same byte keep the order the
    // walk found them in.
    facts.sort_by_key(|fact| fact.span().start_byte);
    Analysis { facts, resolutions }
}

/// Where an expression sits, which decides whether `$event` may appear in
/// it. A command may only be a handler's whole expression, which
/// [`Walker::handler`] checks before any expression is walked, so every
/// command the walk meets as an expression is misplaced.
#[derive(Clone, Copy)]
enum Place<'m> {
    /// Anywhere but inside a handler command's arguments.
    Value,
    /// Inside the arguments of an `on.` handler's command.
    HandlerArgument(Payload<'m>),
}

/// What `$event` is in a handler.
#[derive(Clone, Copy)]
enum Payload<'m> {
    /// The event declares a payload.
    Value,
    /// The event is declared without a payload.
    None { component: &'m str, event: &'m str },
    /// The event, or the element's component, isn't declared. That is
    /// already reported, so `$event` is accepted silently.
    Unknown,
}

struct Walker<'m> {
    template: Template<'m>,
    facts: Vec<Fact>,
    resolutions: Vec<Resolution>,
}

impl<'m> Walker<'m> {
    fn resolve(&mut self, span: Span, target: Target) {
        self.resolutions.push(Resolution { span, target });
    }

    /// Checks one element as an instance of the component its tag names,
    /// then its attribute values, its handlers and its children.
    fn element(&mut self, element: &Element) {
        let manifest = self.template.manifest();
        let component = match manifest.components().get_key_value(&element.name) {
            Some((name, component)) => {
                self.resolve(element.name_span, Target::Component(name.clone()));
                Some((name.as_str(), component))
            }
            None => {
                self.facts.push(Fact::UnknownComponent {
                    name: element.name.clone(),
                    span: element.name_span,
                    candidates: manifest.components().keys().cloned().collect(),
                });
                None
            }
        };

        if let Some((name, component)) = component {
            self.missing_props(element, name, component);
        }

        for attribute in &element.attributes {
            if let Some((name, component)) = component {
                if component.props.contains_key(&attribute.name) {
                    self.resolve(
                        attribute.name_span,
                        Target::Prop {
                            component: name.to_string(),
                            prop: attribute.name.clone(),
                        },
                    );
                } else {
                    self.facts.push(Fact::UnknownProp {
                        component: name.to_string(),
                        prop: attribute.name.clone(),
                        span: attribute.name_span,
                        candidates: component.props.keys().cloned().collect(),
                    });
                }
            }
            match &attribute.value {
                AttributeValue::String { .. } => {}
                AttributeValue::Expression(expression) => {
                    self.expression(expression, Place::Value);
                }
            }
        }

        for binding in &element.event_bindings {
            let payload = match component {
                Some((name, component)) => match component.events.get_key_value(&binding.name) {
                    Some((event, declared)) => {
                        self.resolve(
                            binding.name_span,
                            Target::Event {
                                component: name.to_string(),
                                event: event.clone(),
                            },
                        );
                        match &declared.payload {
                            Some(_) => Payload::Value,
                            None => Payload::None {
                                component: name,
                                event,
                            },
                        }
                    }
                    None => {
                        self.facts.push(Fact::UnknownEvent {
                            component: name.to_string(),
                            event: binding.name.clone(),
                            span: binding.name_span,
                            candidates: component.events.keys().cloned().collect(),
                        });
                        Payload::Unknown
                    }
                },
                None => Payload::Unknown,
            };
            self.handler(&binding.name, &binding.handler, payload);
        }

        for child in &element.children {
            match child {
                Child::Text { .. } => {}
                Child::Expression(expression) => self.expression(expression, Place::Value),
                Child::Element(child) => self.element(child),
            }
        }
    }

    /// Every prop `component` declares required that `element` doesn't
    /// supply, in the manifest's order, each at the tag name.
    fn missing_props(&mut self, element: &Element, name: &str, component: &Component) {
        for (prop, field) in &component.props {
            let supplied = element
                .attributes
                .iter()
                .any(|attribute| &attribute.name == prop);
            if field.required && !supplied {
                self.facts.push(Fact::MissingRequiredProp {
                    component: name.to_string(),
                    prop: prop.clone(),
                    span: element.name_span,
                });
            }
        }
    }

    /// An `on.` handler must be exactly one command invocation. Anything
    /// else is reported once and not looked inside.
    fn handler(&mut self, event: &str, handler: &Expression, payload: Payload<'m>) {
        match handler {
            Expression::Command {
                command,
                command_span,
                arguments,
                span,
            } => self.command(
                command,
                *command_span,
                arguments,
                *span,
                Place::HandlerArgument(payload),
            ),
            other => self.facts.push(Fact::HandlerNotCommand {
                event: event.to_string(),
                span: other.span(),
            }),
        }
    }

    /// A command in handler position: resolves its name and checks its
    /// arity, then walks its arguments in `place`.
    fn command(
        &mut self,
        command: &str,
        command_span: Span,
        arguments: &[Expression],
        span: Span,
        place: Place<'m>,
    ) {
        let commands = &self.template.component().commands;
        match commands.get_key_value(command) {
            Some((name, declared)) => {
                self.resolve(command_span, Target::Command(name.clone()));
                if declared.parameters.len() != arguments.len() {
                    self.facts.push(Fact::CommandArityMismatch {
                        command: command.to_string(),
                        expected: declared.parameters.len(),
                        found: arguments.len(),
                        span,
                    });
                }
            }
            None => self.facts.push(Fact::UnknownCommand {
                command: command.to_string(),
                span: command_span,
                candidates: commands.keys().cloned().collect(),
            }),
        }
        for argument in arguments {
            self.expression(argument, place);
        }
    }

    fn expression(&mut self, expression: &Expression, place: Place<'m>) {
        match expression {
            Expression::Literal { .. } => {}
            Expression::Reference { name, span } => {
                let scope = &self.template.component().scope;
                match scope.get_key_value(name) {
                    Some((name, _)) => self.resolve(*span, Target::Scope(name.clone())),
                    None => self.facts.push(Fact::UnknownReference {
                        name: name.clone(),
                        span: *span,
                        candidates: scope.keys().cloned().collect(),
                    }),
                }
            }
            // The property is resolved against the object's type, which
            // is expression typing's job.
            Expression::MemberAccess { object, .. } => self.expression(object, place),
            Expression::Unary { operand, .. } => self.expression(operand, place),
            Expression::Binary { left, right, .. } => {
                self.expression(left, place);
                self.expression(right, place);
            }
            Expression::Conditional {
                condition,
                consequent,
                alternate,
                ..
            } => {
                self.expression(condition, place);
                self.expression(consequent, place);
                self.expression(alternate, place);
            }
            Expression::Array { elements, .. } => {
                for element in elements {
                    self.expression(element, place);
                }
            }
            Expression::Object { members, .. } => {
                for member in members {
                    self.expression(&member.value, place);
                }
            }
            // A handler's own command never gets here (see `handler`), so
            // this one is misplaced. It is reported once, and neither its
            // name nor its arguments are checked.
            Expression::Command { command, span, .. } => {
                self.facts.push(Fact::CommandOutsideHandler {
                    command: command.clone(),
                    span: *span,
                });
            }
            Expression::EventValue { name, span } => self.event_value(name, *span, place),
        }
    }

    fn event_value(&mut self, name: &str, span: Span, place: Place<'m>) {
        if name != "event" {
            self.facts.push(Fact::UnknownSpecialValue {
                name: name.to_string(),
                span,
                candidates: vec!["event".to_string()],
            });
            return;
        }
        match place {
            Place::Value => self.facts.push(Fact::EventValueOutsideHandler { span }),
            Place::HandlerArgument(Payload::None { component, event }) => {
                self.facts.push(Fact::EventHasNoPayload {
                    component: component.to_string(),
                    event: event.to_string(),
                    span,
                });
            }
            Place::HandlerArgument(Payload::Value | Payload::Unknown) => {}
        }
    }
}

