//! `is_assignable` and `join`, one test per rule of outline D9, plus the
//! outline's own `any` / `any?` cases.

use mesh_analysis::{is_assignable, join, FieldTy, Ty};
use mesh_manifest::Manifest;
use std::collections::BTreeMap;

/// `Name` is an alias of `string`, `MaybeName` of `string?`, and `User` a
/// record type.
fn manifest() -> Manifest {
    mesh_manifest::load(
        r#"{ "version": 1, "components": {}, "types": {
            "Name": { "kind": "string" },
            "MaybeName": { "kind": "optional", "type": { "kind": "string" } },
            "User": { "kind": "record", "fields": {
                "name": { "type": { "kind": "named", "name": "Name" }, "required": true }
            } }
        } }"#,
    )
    .expect("the test manifest loads")
}

fn opt(ty: Ty) -> Ty {
    Ty::Optional(Box::new(ty))
}

fn list(ty: Ty) -> Ty {
    Ty::List(Box::new(ty))
}

fn named(name: &str) -> Ty {
    Ty::Named(name.to_string())
}

/// A record from `(name, type, required)` triples.
fn record(fields: &[(&str, Ty, bool)]) -> Ty {
    Ty::Record(
        fields
            .iter()
            .map(|(name, ty, required)| {
                (
                    name.to_string(),
                    FieldTy {
                        ty: ty.clone(),
                        required: *required,
                    },
                )
            })
            .collect::<BTreeMap<_, _>>(),
    )
}

fn assignable(actual: &Ty, expected: &Ty) -> bool {
    is_assignable(&manifest(), actual, expected)
}

fn common(a: &Ty, b: &Ty) -> Option<Ty> {
    join(&manifest(), a, b)
}

#[test]
fn rule_1_void_is_compatible_with_nothing() {
    for other in [Ty::Any, opt(Ty::Any), Ty::Void, Ty::Nothing, Ty::String] {
        assert!(!assignable(&Ty::Void, &other), "void -> {other}");
        assert!(!assignable(&other, &Ty::Void), "{other} -> void");
    }
}

#[test]
fn rule_2_optionality_is_checked_first() {
    // A present value satisfies "may be absent".
    assert!(assignable(&Ty::String, &opt(Ty::String)));
    assert!(assignable(&opt(Ty::String), &opt(Ty::String)));
    // A possibly absent value satisfies only that.
    assert!(!assignable(&opt(Ty::String), &Ty::String));
    // `null` is a value, not absence.
    assert!(!assignable(&Ty::Null, &opt(Ty::String)));
    // Through aliases, too.
    assert!(!assignable(&named("MaybeName"), &named("Name")));
    assert!(assignable(&named("Name"), &named("MaybeName")));
}

/// The outline's `any` conformance cases: absence is never unchecked.
#[test]
fn rule_2_applies_to_any_too() {
    assert!(assignable(&Ty::Any, &Ty::String));
    assert!(!assignable(&opt(Ty::Any), &Ty::String));
    assert!(assignable(&opt(Ty::Any), &opt(Ty::String)));
    assert!(!assignable(&opt(Ty::String), &Ty::Any));
    assert!(assignable(&opt(Ty::String), &opt(Ty::Any)));
}

#[test]
fn rule_3_anything_present_fits_any() {
    for actual in [
        Ty::String,
        Ty::Null,
        Ty::Nothing,
        list(Ty::Number),
        named("User"),
    ] {
        assert!(assignable(&actual, &Ty::Any), "{actual} -> any");
    }
}

#[test]
fn rule_4_any_fits_anything_present() {
    for expected in [Ty::String, Ty::Null, list(Ty::Number), named("User")] {
        assert!(assignable(&Ty::Any, &expected), "any -> {expected}");
    }
}

#[test]
fn rule_5_nothing_fits_everything() {
    assert!(assignable(&Ty::Nothing, &Ty::String));
    assert!(assignable(&Ty::Nothing, &named("User")));
    assert!(assignable(&list(Ty::Nothing), &list(named("User"))));
}

#[test]
fn rule_6_primitives_match_exactly() {
    let primitives = [Ty::String, Ty::Number, Ty::Boolean, Ty::Null];
    for actual in &primitives {
        for expected in &primitives {
            assert_eq!(
                assignable(actual, expected),
                actual == expected,
                "{actual} -> {expected}"
            );
        }
    }
    assert!(assignable(&named("Name"), &Ty::String));
}

#[test]
fn rule_7_lists_are_covariant() {
    assert!(assignable(&list(Ty::String), &list(opt(Ty::String))));
    assert!(!assignable(&list(opt(Ty::String)), &list(Ty::String)));
    assert!(!assignable(&list(Ty::String), &list(Ty::Number)));
}

#[test]
fn rule_8_records_compare_declarations_exactly() {
    let t = || Ty::String;
    // A required field must be declared required, with a fitting type.
    let expected = record(&[("f", t(), true)]);
    assert!(assignable(&record(&[("f", t(), true)]), &expected));
    assert!(!assignable(&record(&[("f", t(), false)]), &expected));
    assert!(!assignable(&record(&[]), &expected));
    assert!(!assignable(&record(&[("f", Ty::Number, true)]), &expected));
    // An optional field may be left out, or declared either way.
    let expected = record(&[("f", t(), false)]);
    assert!(assignable(&record(&[]), &expected));
    assert!(assignable(&record(&[("f", t(), true)]), &expected));
    assert!(assignable(&record(&[("f", t(), false)]), &expected));
    // Exact: no field the expected record lacks.
    assert!(!assignable(
        &record(&[("f", t(), true), ("g", t(), true)]),
        &record(&[("f", t(), true)])
    ));
    // `f?: T` and `f: T?` aren't interchangeable, either way.
    assert!(!assignable(
        &record(&[("f", t(), false)]),
        &record(&[("f", opt(t()), true)])
    ));
    assert!(!assignable(
        &record(&[("f", opt(t()), true)]),
        &record(&[("f", t(), false)])
    ));
    // Named types are expanded, fields included.
    assert!(assignable(
        &record(&[("name", Ty::String, true)]),
        &named("User")
    ));
}

#[test]
fn rule_9_anything_else_fails() {
    assert!(!assignable(&list(Ty::String), &named("User")));
    assert!(!assignable(&Ty::String, &list(Ty::String)));
    assert!(!assignable(&named("User"), &Ty::String));
}

#[test]
fn join_rule_1_void_has_no_common_type() {
    for other in [Ty::Void, Ty::Any, Ty::Nothing, Ty::String] {
        assert_eq!(common(&Ty::Void, &other), None, "void, {other}");
        assert_eq!(common(&other, &Ty::Void), None, "{other}, void");
    }
}

#[test]
fn join_rule_2_optionality_is_kept() {
    assert_eq!(common(&opt(Ty::String), &Ty::String), Some(opt(Ty::String)));
    assert_eq!(common(&Ty::String, &opt(Ty::String)), Some(opt(Ty::String)));
    assert_eq!(common(&Ty::Any, &opt(Ty::String)), Some(opt(Ty::Any)));
    // `null` is not absence.
    assert_eq!(common(&opt(Ty::String), &Ty::Null), None);
}

#[test]
fn join_rule_3_nothing_adds_nothing() {
    assert_eq!(common(&Ty::Nothing, &named("User")), Some(named("User")));
    assert_eq!(common(&Ty::String, &Ty::Nothing), Some(Ty::String));
}

#[test]
fn join_rule_4_any_absorbs_present_types() {
    assert_eq!(common(&Ty::Any, &named("User")), Some(Ty::Any));
    assert_eq!(common(&Ty::Number, &Ty::Any), Some(Ty::Any));
}

#[test]
fn join_rule_5_identical_types_join_to_themselves() {
    assert_eq!(common(&Ty::String, &Ty::String), Some(Ty::String));
    assert_eq!(common(&named("Name"), &Ty::String), Some(named("Name")));
    let user = record(&[("name", Ty::String, true)]);
    assert_eq!(common(&user, &named("User")), Some(user.clone()));
    // `{f?: T}` and `{f: T?}` aren't identical.
    assert_eq!(
        common(
            &record(&[("f", Ty::String, false)]),
            &record(&[("f", opt(Ty::String), true)])
        ),
        None
    );
}

#[test]
fn join_rule_6_lists_join_element_wise() {
    assert_eq!(
        common(&list(Ty::Nothing), &list(Ty::String)),
        Some(list(Ty::String))
    );
    assert_eq!(
        common(&list(Ty::String), &list(opt(Ty::String))),
        Some(list(opt(Ty::String)))
    );
    assert_eq!(common(&list(Ty::String), &list(Ty::Number)), None);
}

#[test]
fn join_rule_7_anything_else_has_no_common_type() {
    assert_eq!(common(&Ty::String, &Ty::Number), None);
    assert_eq!(common(&Ty::Null, &Ty::String), None);
    assert_eq!(common(&list(Ty::String), &Ty::String), None);
}

/// `join` never invents compatibility that `is_assignable` would deny:
/// both inputs are assignable to their join, whenever there is one.
#[test]
fn both_sides_are_assignable_to_their_join() {
    let types = [
        Ty::String,
        Ty::Number,
        Ty::Null,
        Ty::Any,
        Ty::Nothing,
        opt(Ty::String),
        opt(Ty::Any),
        named("Name"),
        named("MaybeName"),
        named("User"),
        list(Ty::Nothing),
        list(Ty::String),
        list(opt(Ty::String)),
        record(&[("f", Ty::String, false)]),
    ];
    for a in &types {
        for b in &types {
            if let Some(joined) = common(a, b) {
                assert!(assignable(a, &joined), "{a} -> join({a}, {b}) = {joined}");
                assert!(assignable(b, &joined), "{b} -> join({a}, {b}) = {joined}");
            }
        }
    }
}

#[test]
fn types_display_in_the_docs_notation() {
    assert_eq!(opt(list(named("User"))).to_string(), "list<User>?");
    assert_eq!(
        record(&[
            ("name", Ty::String, true),
            ("avatar", opt(Ty::String), false)
        ])
        .to_string(),
        "{ avatar?: string?, name: string }"
    );
    assert_eq!(record(&[]).to_string(), "{}");
    assert_eq!(list(Ty::Nothing).to_string(), "list<nothing>");
    assert_eq!(Ty::Void.to_string(), "void");
}

//! The types analysis works with: every type a manifest can write, plus
//! the two internal types (`nothing` and `void`), in one representation.

use std::collections::BTreeMap;
use std::fmt;

/// A type, as analysis computes and compares them.
///
/// The variants a manifest can write mirror [`mesh_manifest::Type`]
/// (convert with `Ty::from`); [`Ty::Nothing`] and [`Ty::Void`] exist only
/// inside analysis. Named references stay [`Ty::Named`], so a type prints
/// the way the manifest wrote it; [`crate::is_assignable`] and
/// [`crate::join`] expand them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ty {
    String,
    Number,
    Boolean,
    /// The value `null`. Not absence: that is [`Ty::Optional`].
    Null,
    /// Any present value.
    Any,
    /// `list<T>`.
    List(Box<Ty>),
    /// An exact record: these fields, and no others.
    Record(BTreeMap<String, FieldTy>),
    /// A reference to one of the manifest's named types.
    Named(String),
    /// `T?`: a `T`, or absent. Never wraps a type that is already
    /// optional, directly or through named references.
    Optional(Box<Ty>),
    /// The element type of `[]`. Assignable to every type.
    Nothing,
    /// The result of a command invocation. Compatible with nothing.
    Void,
}

/// A record field's declaration: its type, and whether it must be
/// supplied.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FieldTy {
    pub ty: Ty,
    pub required: bool,
}

impl From<&mesh_manifest::Type> for Ty {
    fn from(ty: &mesh_manifest::Type) -> Self {
        use mesh_manifest::Type;
        match ty {
            Type::String => Ty::String,
            Type::Number => Ty::Number,
            Type::Boolean => Ty::Boolean,
            Type::Null => Ty::Null,
            Type::Any => Ty::Any,
            Type::List(element) => Ty::List(Box::new(Ty::from(element.as_ref()))),
            Type::Record(fields) => Ty::Record(
                fields
                    .iter()
                    .map(|(name, field)| {
                        (
                            name.clone(),
                            FieldTy {
                                ty: Ty::from(&field.ty),
                                required: field.required,
                            },
                        )
                    })
                    .collect(),
            ),
            Type::Named(name) => Ty::Named(name.clone()),
            Type::Optional(inner) => Ty::Optional(Box::new(Ty::from(inner.as_ref()))),
        }
    }
}

/// The notation the language docs use: `string`, `list<User>`, `boolean?`,
/// `{ name: string, avatar?: string }`. A named type prints as its name.
impl fmt::Display for Ty {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Ty::String => f.write_str("string"),
            Ty::Number => f.write_str("number"),
            Ty::Boolean => f.write_str("boolean"),
            Ty::Null => f.write_str("null"),
            Ty::Any => f.write_str("any"),
            Ty::Nothing => f.write_str("nothing"),
            Ty::Void => f.write_str("void"),
            Ty::List(element) => write!(f, "list<{element}>"),
            Ty::Named(name) => f.write_str(name),
            Ty::Optional(inner) => write!(f, "{inner}?"),
            Ty::Record(fields) if fields.is_empty() => f.write_str("{}"),
            Ty::Record(fields) => {
                f.write_str("{ ")?;
                for (index, (name, field)) in fields.iter().enumerate() {
                    if index > 0 {
                        f.write_str(", ")?;
                    }
                    let mark = if field.required { "" } else { "?" };
                    write!(f, "{name}{mark}: {}", field.ty)?;
                }
                f.write_str(" }")
            }
        }
    }
}

//! The one compatibility relation, `is_assignable`, and the common type,
//! `join` (outline D9). Every check that compares types goes through
//! these two functions; no checker has compatibility logic of its own.

use crate::types::Ty;
use mesh_manifest::Manifest;

/// `ty` with named references at its top level followed to their
/// definition. The result is never [`Ty::Named`].
pub(crate) fn expand(manifest: &Manifest, ty: &Ty) -> Ty {
    let mut ty = ty.clone();
    while let Ty::Named(name) = &ty {
        ty = Ty::from(&manifest.types()[name]);
    }
    ty
}

/// `ty?`, unless `ty` is already optional (directly or through named
/// references), in which case `ty` itself: optionality never nests.
pub(crate) fn optional(manifest: &Manifest, ty: Ty) -> Ty {
    match expand(manifest, &ty) {
        Ty::Optional(_) => ty,
        _ => Ty::Optional(Box::new(ty)),
    }
}

/// Whether a value of type `actual` may be used where `expected` is
/// expected: outline D9's `is_assignable`, rule by rule. Named references
/// are expanded first, and the first matching rule decides.
///
/// `manifest` must be the manifest the types came from, so that every
/// named reference in them resolves.
pub fn is_assignable(manifest: &Manifest, actual: &Ty, expected: &Ty) -> bool {
    let actual = expand(manifest, actual);
    let expected = expand(manifest, expected);
    match (&actual, &expected) {
        // 1. `void` is compatible with nothing, not even `any`.
        (Ty::Void, _) | (_, Ty::Void) => false,
        // 2. Optionality, for every type, `any` included. A present value
        //    satisfies "may be absent"; a possibly absent one satisfies
        //    only that.
        (Ty::Optional(actual), Ty::Optional(expected)) => is_assignable(manifest, actual, expected),
        (_, Ty::Optional(expected)) => is_assignable(manifest, &actual, expected),
        (Ty::Optional(_), _) => false,
        // 3, 4. `any` is unchecked against the value's type, either way.
        (_, Ty::Any) | (Ty::Any, _) => true,
        // 5. `nothing` (the elements of `[]`) fits everywhere.
        (Ty::Nothing, _) => true,
        // 6. Primitives: the same type, and no coercions.
        (Ty::String, Ty::String)
        | (Ty::Number, Ty::Number)
        | (Ty::Boolean, Ty::Boolean)
        | (Ty::Null, Ty::Null) => true,
        // 7. Lists are covariant: MPRX values are never mutated.
        (Ty::List(actual), Ty::List(expected)) => is_assignable(manifest, actual, expected),
        // 8. Records compare declarations, requiredness included, and are
        //    exact.
        (Ty::Record(actual), Ty::Record(expected)) => {
            let fits = expected.iter().all(|(name, expected)| {
                match (actual.get(name), expected.required) {
                    (Some(actual), true) => {
                        actual.required && is_assignable(manifest, &actual.ty, &expected.ty)
                    }
                    (Some(actual), false) => is_assignable(manifest, &actual.ty, &expected.ty),
                    (None, required) => !required,
                }
            });
            fits && actual.keys().all(|name| expected.contains_key(name))
        }
        // 9. Anything else.
        _ => false,
    }
}

/// The common type of `a` and `b`, if they have one: outline D9's `join`,
/// used for conditional branches, array elements and equality operands.
/// Named references are expanded first, and the first matching rule
/// decides. Where the result is one of the arguments, it is returned as
/// written, so a named type keeps its name.
///
/// `manifest` must be the manifest the types came from.
pub fn join(manifest: &Manifest, a: &Ty, b: &Ty) -> Option<Ty> {
    let expanded_a = expand(manifest, a);
    let expanded_b = expand(manifest, b);
    match (&expanded_a, &expanded_b) {
        // 1. Nothing joins with `void`.
        (Ty::Void, _) | (_, Ty::Void) => None,
        // 2. Optionality is never discarded, `any` included.
        (Ty::Optional(a), Ty::Optional(b)) => Some(optional(manifest, join(manifest, a, b)?)),
        (Ty::Optional(a), _) => Some(optional(manifest, join(manifest, a, &expanded_b)?)),
        (_, Ty::Optional(b)) => Some(optional(manifest, join(manifest, &expanded_a, b)?)),
        // 3. `nothing` adds nothing.
        (Ty::Nothing, _) => Some(b.clone()),
        (_, Ty::Nothing) => Some(a.clone()),
        // 4. `any` absorbs every present type.
        (Ty::Any, _) | (_, Ty::Any) => Some(Ty::Any),
        // 5. Structurally identical types.
        _ if identical(manifest, &expanded_a, &expanded_b) => Some(a.clone()),
        // 6. Lists join element-wise.
        (Ty::List(a), Ty::List(b)) => Some(Ty::List(Box::new(join(manifest, a, b)?))),
        // 7. Anything else.
        _ => None,
    }
}

/// Whether `a` and `b` are the same type once every named reference in
/// them is expanded. Records must declare the same fields, each with the
/// same requiredness and an identical type.
fn identical(manifest: &Manifest, a: &Ty, b: &Ty) -> bool {
    match (expand(manifest, a), expand(manifest, b)) {
        (Ty::List(a), Ty::List(b)) | (Ty::Optional(a), Ty::Optional(b)) => {
            identical(manifest, &a, &b)
        }
        (Ty::Record(a), Ty::Record(b)) => {
            a.len() == b.len()
                && a.iter().all(|(name, a)| {
                    b.get(name).is_some_and(|b| {
                        a.required == b.required && identical(manifest, &a.ty, &b.ty)
                    })
                })
        }
        (a, b) => a == b,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `Maybe` is `string?`, and `Alias` is `Maybe` through one more name.
    fn manifest() -> Manifest {
        mesh_manifest::load(
            r#"{ "version": 1, "components": {}, "types": {
                "Maybe": { "kind": "optional", "type": { "kind": "string" } },
                "Alias": { "kind": "named", "name": "Maybe" },
                "Name": { "kind": "string" }
            } }"#,
        )
        .expect("the test manifest loads")
    }

    fn named(name: &str) -> Ty {
        Ty::Named(name.to_string())
    }

    fn opt(ty: Ty) -> Ty {
        Ty::Optional(Box::new(ty))
    }

    #[test]
    fn expands_named_references_at_the_top_level_only() {
        let manifest = manifest();
        assert_eq!(expand(&manifest, &named("Alias")), opt(Ty::String));
        let list = Ty::List(Box::new(named("Name")));
        assert_eq!(expand(&manifest, &list), list);
    }

    #[test]
    fn optionality_never_nests() {
        let manifest = manifest();
        assert_eq!(optional(&manifest, Ty::String), opt(Ty::String));
        assert_eq!(optional(&manifest, opt(Ty::String)), opt(Ty::String));
        assert_eq!(optional(&manifest, named("Alias")), named("Alias"));
        assert_eq!(optional(&manifest, named("Name")), opt(named("Name")));
    }

    #[test]
    fn named_types_are_aliases() {
        let manifest = manifest();
        assert!(is_assignable(&manifest, &named("Name"), &Ty::String));
        assert!(is_assignable(&manifest, &Ty::String, &named("Name")));
        assert!(is_assignable(
            &manifest,
            &named("Alias"),
            &opt(named("Name"))
        ));
        assert!(!is_assignable(&manifest, &named("Alias"), &Ty::String));
        assert_eq!(
            join(&manifest, &named("Name"), &Ty::String),
            Some(named("Name"))
        );
        assert_eq!(join(&manifest, &named("Alias"), &Ty::Null), None);
    }

    #[test]
    fn joins_keep_a_named_type_optional_through_its_alias() {
        let manifest = manifest();
        assert_eq!(
            join(&manifest, &named("Alias"), &Ty::String),
            Some(opt(Ty::String))
        );
        assert_eq!(
            join(&manifest, &named("Alias"), &Ty::Nothing),
            Some(opt(Ty::String))
        );
    }
}

