fn member_access_on_a_record_needs_the_field() {
    assert_eq!(
        only_fact("user.nmae"),
        Fact::UnknownMember {
            object: named("User"),
            property: "nmae".to_string(),
            span: span("user.nmae", "nmae"),
            candidates: names(&["avatar", "bio", "label", "name", "nick"]),
